package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.monitoring.*;
import cn.mop.domain.monitoring.MonitoringObjectBinding.*;
import cn.mop.domain.monitoring.MonitoringObjectBindingRepository.*;
import cn.mop.domain.monitoring.MonitoringObjectMapping.*;
import com.fasterxml.jackson.databind.*;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.mock.web.MockHttpServletRequest;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class MonitoringObjectBindingControllerTest {
 final String tenant="79000000-0000-4000-8000-000000000001",actor="79000000-0000-4000-8000-000000000002",id="79000000-0000-4000-8000-000000000003",asset="79000000-0000-4000-8000-000000000004";
 final PlatformRepository platform=mock(PlatformRepository.class);final MonitoringObjectBindingRepository repository=mock(MonitoringObjectBindingRepository.class);final ObjectMapper json=new ObjectMapper().findAndRegisterModules();
 MonitoringObjectBindingController controller(boolean enabled){return new MonitoringObjectBindingController(platform,repository,json,new MockEnvironment().withProperty("MOP_MONITORING_MAPPING_ENABLED",String.valueOf(enabled)));}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest();r.setUserPrincipal(()->actor);r.getSession().setAttribute("mop.tenant_id",tenant);when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"padmin",7,true)));return r;}
 View view(String tenantId){var state=MonitoringObjectBinding.create(new Document(UUID.fromString(id),UUID.fromString(tenantId),new Key(UUID.randomUUID(),ObjectType.HOST,"23"),"ZABBIX_7",UUID.fromString(actor),Instant.parse("2026-10-23T00:00:00Z")),UUID.fromString(asset),1,null);return new View(state,"NO_ACTIVE_MAPPING",true,false,null,null);}
 @Test void disabledDoesNotReadTables(){assertEquals(503,assertThrows(DomainException.class,()->controller(false).get(id,request())).status);verifyNoInteractions(repository);}
 @Test void actorTenantOrderIsExact(){when(repository.get(any(),any())).thenReturn(view(tenant));controller(true).get(id,request());verify(repository).get(argThat(a->tenant.equals(a.tenantId())&&actor.equals(a.actorId())&&a.permissionVersion()==7),eq(UUID.fromString(id)));}
 @Test void returnedForeignTenantFailsClosed(){when(repository.get(any(),any())).thenReturn(view(actor));assertEquals(503,assertThrows(DomainException.class,()->controller(true).get(id,request())).status);}
 @Test void membershipRevocationDuringReadFails(){var r=request();when(repository.get(any(),any())).thenAnswer(c->{when(platform.membership(actor,tenant)).thenReturn(Optional.empty());return view(tenant);});assertEquals(401,assertThrows(DomainException.class,()->controller(true).get(id,r)).status);}
 @Test void roleLossRemovesConfigurationReadAndReturns403EvenSameRevision(){var r=request();when(repository.get(any(),any())).thenAnswer(c->{when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"msp",7,true)));return view(tenant);});assertEquals(403,assertThrows(DomainException.class,()->controller(true).get(id,r)).status);}
 @Test void clientCannotSupplyProofOrTimestamp()throws Exception{for(String field:List.of("source","observed_at","tenant_id","dispatch_allowed")){var body=json.readTree("{\"action\":\"ACTIVATE\",\"expected_version\":1,\"reason\":null,\"expected_policy_reference\":\"v1\",\"expected_source_definition_sha256\":\""+"a".repeat(64)+"\",\""+field+"\":null}");assertEquals(400,assertThrows(DomainException.class,()->controller(true).change(id,body,request())).status);}verifyNoInteractions(repository);}
 @Test void duplicatedCommandKeyRejected()throws Exception{var r=request();r.addHeader("Idempotency-Key","a");r.addHeader("Idempotency-Key","b");var body=json.readTree("{\"action\":\"CANCEL_DRAFT\",\"expected_version\":1,\"reason\":null}");assertEquals(400,assertThrows(DomainException.class,()->controller(true).change(id,body,r)).status);verifyNoInteractions(repository);}
 @Test void commandAcknowledgesOnlyAndIsInsideIdempotency()throws Exception{var r=request();r.setMethod("POST");r.setRequestURI("/api/v1/monitoring-object-mappings/"+id+"/actions");r.addHeader("Idempotency-Key","unit-command");when(platform.idempotentAuthorized(anyString(),anyString(),anyString(),anyString(),anyString(),eq(7L),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(repository.change(any(),any(),any(),anyLong(),any(),any(),any(),any(),any())).thenReturn(new Receipt(UUID.fromString(id),2,Action.CANCEL_DRAFT));var body=json.readTree("{\"action\":\"CANCEL_DRAFT\",\"expected_version\":1,\"reason\":null}");var result=(Map<?,?>)controller(true).change(id,body,r);var data=(Map<?,?>)result.get("data");assertEquals(true,data.get("acknowledgement_only"));assertEquals(false,data.get("current_mapping_claimed"));assertEquals(false,data.get("dispatch_allowed"));verify(repository).authorize(any(),eq(UUID.fromString(id)),eq(true));}
 @Test void listRejectsTenantOverrideOrHalfCursor(){for(String key:List.of("tenant_id","before","unknown")){var r=request();r.addParameter("asset_id",asset);r.addParameter(key,"bad");assertEquals(400,assertThrows(DomainException.class,()->controller(true).list(r)).status);}verifyNoInteractions(repository);}
 @Test void cachedCreateStillChecksCurrentAssetVisibility()throws Exception{var r=request();r.setMethod("POST");r.setRequestURI("/api/v1/monitoring-object-mappings");r.addHeader("Idempotency-Key","replay-create");when(platform.idempotentAuthorized(anyString(),anyString(),anyString(),anyString(),anyString(),eq(7L),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("acknowledgement_only",true);});when(platform.authorizedAsset(eq(tenant),eq(actor),eq(7L),eq(asset))).thenReturn(Optional.empty());var body=json.valueToTree(new HashMap<String,Object>(){{put("asset_id",asset);put("asset_version",1);put("pool_id",tenant);put("object_type","HOST");put("external_id","23");put("reason",null);}});assertEquals(404,assertThrows(DomainException.class,()->controller(true).create(body,r)).status);verify(repository,never()).create(any(),any(),anyLong(),any(),any());}
 MonitoringObjectBindingController captureController(){return new MonitoringObjectBindingController(platform,repository,json,new MockEnvironment().withProperty("MOP_MONITORING_MAPPING_ENABLED","true").withProperty("MOP_MONITORING_MAPPING_CAPTURE_ENABLED","true"));}
 JsonNode captureBody(){return json.valueToTree(Map.of("expected_version",2,"source_event_id","44","expected_source_definition_sha256","a".repeat(64)));}
 @Test void captureIsSeparatelyDisabledByDefault(){var r=request();r.setMethod("POST");r.setRequestURI("/api/v1/monitoring-object-mappings/"+id+"/captures");r.addHeader("Idempotency-Key","capture-disabled");when(platform.idempotentAuthorized(anyString(),anyString(),anyString(),anyString(),anyString(),eq(7L),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});assertEquals(503,assertThrows(DomainException.class,()->controller(true).capture(id,captureBody(),r)).status);verify(repository,never()).capture(any(),any(),anyLong(),any(),any());}
 @Test void disabledCaptureCanStillReconcileAnExistingAuthorizedAcknowledgment(){var r=request();r.setMethod("POST");r.setRequestURI("/api/v1/monitoring-object-mappings/"+id+"/captures");r.addHeader("Idempotency-Key","original-capture");when(platform.idempotentAuthorized(anyString(),anyString(),anyString(),anyString(),anyString(),eq(7L),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("acknowledgement_only",true,"business_processed",false);});var reply=(Map<?,?>)controller(true).capture(id,captureBody(),r);assertEquals(true,((Map<?,?>)reply.get("data")).get("acknowledgement_only"));verify(repository).authorize(any(),eq(UUID.fromString(id)),eq(true));verify(repository,never()).capture(any(),any(),anyLong(),any(),any());}
 @Test void captureCannotAcceptPayloadOrTimeProofOverride(){var body=(com.fasterxml.jackson.databind.node.ObjectNode)captureBody();body.put("payload","client supplied");assertEquals(400,assertThrows(DomainException.class,()->captureController().capture(id,body,request())).status);verifyNoInteractions(repository);}
 @Test void captureReceiptNeverConfirmsRecoveryOrBusinessProcessing(){var r=request();r.setMethod("POST");r.setRequestURI("/api/v1/monitoring-object-mappings/"+id+"/captures");r.addHeader("Idempotency-Key","capture-once");when(platform.idempotentAuthorized(anyString(),anyString(),anyString(),anyString(),anyString(),eq(7L),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(repository.capture(any(),any(),eq(2L),eq("44"),any())).thenReturn(new CaptureReceipt(UUID.fromString(id),2,"44",RawMonitoringEvent.Phase.RECOVERED,"RAW_STORED",UUID.randomUUID(),Instant.parse("2026-10-24T00:00:00Z")));var response=(Map<?,?>)captureController().capture(id,captureBody(),r);var data=(Map<?,?>)response.get("data");assertEquals("UNVERIFIED",data.get("source_authorization_status"));assertEquals("RECOVERED",data.get("source_phase"));assertEquals(false,data.get("business_processed"));assertEquals(false,data.get("dispatch_allowed"));assertEquals(false,data.get("current_mapping_claimed"));verify(repository).authorize(any(),eq(UUID.fromString(id)),eq(true));}
}
